// Characterization tests: pin CURRENT behaviour of order totals, bugs included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 33.33, D: 0.1, E: 100, F: 100.01, G: 9.99 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const totalFor = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

test('total is sum of price*qty, floored to whole euros (no discount at or below 100)', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 3 }]), 30)
  assert.equal(await totalFor([{ sku: 'B', qty: 3 }]), 76) // 76.5 floored
  assert.equal(await totalFor([{ sku: 'D', qty: 1 }]), 0) // 0.1 floored
  assert.equal(await totalFor([{ sku: 'G', qty: 1 }]), 9)
})

test('discount threshold is strict: exactly 100 gets no discount', async () => {
  assert.equal(await totalFor([{ sku: 'E', qty: 1 }]), 100)
})

test('just over 100 gets 10% off and is floored (BUG-suspect: 100.01 -> 90)', async () => {
  assert.equal(await totalFor([{ sku: 'F', qty: 1 }]), 90)
})

test('discount is a flat 10% regardless of order size (no tiers)', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99) // 110 -> 99
  assert.equal(await totalFor([{ sku: 'E', qty: 10 }]), 900) // 1000 -> 900
  assert.equal(await totalFor([{ sku: 'E', qty: 1000 }]), 90000)
})

test('discounted totals floor fractional cents away (BUG-suspect: always rounds down)', async () => {
  assert.equal(await totalFor([{ sku: 'C', qty: 4 }]), 119) // 133.32*.9=119.988
  assert.equal(await totalFor([{ sku: 'B', qty: 5 }]), 114) // 127.5*.9=114.75
})

test('discount applies to the whole multi-line order sum, not per line', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 6 }, { sku: 'B', qty: 2 }]), 100) // 111 -> 99.9 -> 99? see below
})

test('floating point artefacts are visible in totals', async () => {
  // 0.1 * 3 = 0.30000000000000004 -> 0
  assert.equal(await totalFor([{ sku: 'D', qty: 3 }]), 0)
  // 1000 * 0.1 = 100 exactly; 1001 * 0.1 -> 100.10000000000001 -> discounted 90.09 -> 90
  assert.equal(await totalFor([{ sku: 'D', qty: 1001 }]), 90)
})

test('qty 0 and negative qty are accepted and affect total (no validation)', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 0 }]), 0)
  assert.equal(await totalFor([{ sku: 'A', qty: -2 }]), -20)
})

test('unknown sku (undefined price) yields null total (NaN serialised)', async () => {
  const res = await post({ items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('response shape, incrementing ids, and retrieval', async () => {
  const items = [{ sku: 'A', qty: 2 }]
  const a = await (await post({ items })).json()
  const b = await (await post({ items })).json()
  assert.deepEqual(a, { id: a.id, items, total: 20 })
  assert.equal(Number(b.id), Number(a.id) + 1)
  const got = await fetch(`${base}/orders/${a.id}`)
  assert.equal(got.status, 200)
  assert.deepEqual(await got.json(), a)
})

test('validation and error statuses as currently implemented', async () => {
  for (const body of [{}, { items: [] }, { items: 'x' }]) {
    const res = await post(body)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
  assert.equal((await post(null, '{not json')).status, 400)
  const missing = await fetch(`${base}/orders/nope`)
  assert.equal(missing.status, 200) // BUG-suspect: not found returned as 200
  assert.deepEqual(await missing.json(), { error: 'not found' })
  const none = await fetch(`${base}/nothing`)
  assert.equal(none.status, 404)
  assert.deepEqual(await none.json(), { error: 'no route' })
})
EOF
